{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "we included cohort studies of pregnant and recently pregnant women who sought hospital care for any reason and had a diagnosis of SARS-CoV-2 infection, and where SARSCoV-2 status was ascertained in the fetus or neonate using RT-PCR ... or serological tests (antiSARS-CoV-2 IgM), or both. We defined cohort studies as those that sampled consecutive women, who were followed-up to ascertain the SARS-CoV-2 status of their offspring within the first 30 days after birth.",
      "reason": "Study designs (cohorts, case series/reports), population, exposure, outcome ascertainment tests, and follow-up requirements (within first 30 days) are clearly specified for each synthesis aim."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "For this update of the living systematic review, we included studies from searches up to 25 April 2022. No language restrictions were applied.",
      "reason": "Language (no restrictions) and a search date limit are reported, but publication status restrictions are not explicitly stated as eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion of studies because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "To assess SARSCoV-2 positivity rates in offspring, we included cohort studies... In addition to the cohort studies, we included case series and case reports to assess the timing of motherto-child transmission and likelihood of infection. To evaluate maternal risk factors for offspring SARS-CoV-2 positivity, we included cohort studies... that reported on maternal and perinatal risk factors such as maternal severe covid-19... mode of delivery (caesarean section v vaginal birth)...",
      "reason": "Groups for each synthesis (positivity rates, timing of transmission, risk factor comparisons) are specified and linked to the review objectives and comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "We only included cohort studies for estimating the rates of SARS-CoV-2 positivity in offspring, unlike some of the published systematic reviews, which combined cohort and case-control studies with case series",
      "reason": "A rationale for the notable restriction to cohort studies for estimating positivity rates is provided in the strengths section."
    }
  ],
  "confidence": 85
}

