{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Using a pre-piloted form, six independent reviewers in two sets extracted data on study design, number of pregnant women with SARS-CoV-2 infection, type of SARS-CoV-2 test in mothers and babies (RT-PCR, IgM), maternal characteristics (including stage of pregnancy at diagnosis), severity of covid-19 (as defined by authors), mode of delivery, type of samples tested (neonatal nasopharyngeal, rectal, or faecal swabs, neonatal or cord blood, fetal tissue, placenta, amniotic fluid, vaginal fluid, breast milk), timing of sample collection, and SARS-CoV-2 predominant variant of concern",
      "reason": "The data extraction section comprehensively lists the variables sought, including definitions such as severity of covid-19 'as defined by authors' and variant mapping approach."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "SARS-CoV-2 predominant variant of concern 20 (as reported by authors, or mapped to the dominant variant in the country during the study period using https://covariants.org/)",
      "reason": "Assumptions about unclear information are described: variants not reported by authors were mapped to the dominant country variant, and WHO classification with added categories was used to classify timing of transmission when tests were incomplete (per Fig 3 footnotes)."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of a tool used to determine which data items to collect; data items were determined by the authors' pre-piloted form and registered protocol, so this conditional requirement does not apply."
    }
  ],
  "confidence": 82
