    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "The overall risk of bias (Newcastle Ottawa scale) for the included comparative cohort studies was low in 98% (89/91) of studies",
      "reason": "An overall risk-of-bias judgement is reported for the NOS-assessed studies, but the rules used to derive the overall judgement are not explicitly described for either tool."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of adaptations to an existing risk-of-bias tool; standard tools (Hoy et al., NOS) were used as described."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool is reported; existing published tools were used."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Two reviewers independently extracted data and assessed study quality.",
      "reason": "Number of reviewers (two) and independence are reported for quality assessment, but disagreement-resolution procedures specific to risk-of-bias assessment are not described (disagreement resolution is mentioned only for study selection in text_15)."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No process for obtaining or confirming risk-of-bias information from study investigators is reported; author contact related to data duplication/unpublished data, not risk of bias."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools are reported as being used for risk-of-bias assessment."
    }
  ],
