{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "A random effects model was used to synthesise data for rates, with associations reported using odds ratios and 95% confidence intervals. Narrative syntheses were performed when meta-analysis was inappropriate.",
      "reason": "The methods specify the effect measure for each outcome type: rates/proportions for SARS-CoV-2 positivity in offspring (further detailed in text_17: 'After transforming data using Freeman-Tukey double arcsine transformation, we used DerSimonian and Laird random effects meta-analysis to calculate rates and corresponding 95% confidence intervals'), odds ratios with 95% CIs for associations between maternal/perinatal factors and offspring positivity (text_17: 'we pooled comparative dichotomous data as odds ratios and 95% confidence intervals using random effects meta-analysis'), and narrative descriptive synthesis for outcomes where meta-analysis was inappropriate (e.g., clinical outcomes in test-positive babies)."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting the magnitude of effect sizes (e.g., minimal important differences) are mentioned anywhere in the retrieved evidence; the review presents effect estimates with 95% CIs without applying interpretive thresholds, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes no re-expression of synthesized results into a different effect measure (e.g., converting odds ratios to risk ratios). The Freeman-Tukey double arcsine transformation is a variance-stabilizing transformation used to pool proportions, not a re-expression of results using another effect measure, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although odds ratios (for comparative dichotomous data) and proportions/rates (for positivity) are specified as effect measures, no rationale or justification for choosing these effect measures is provided anywhere in the retrieved evidence."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_13a",
